-- DuckDB cannot enforce cross-schema foreign keys. The importer validates worksheet endpoints.
CREATE TABLE question_register_identity (question_id INTEGER PRIMARY KEY REFERENCES research_question(question_id), workshop_question_id VARCHAR NOT NULL UNIQUE, relation_type VARCHAR NOT NULL, basis VARCHAR NOT NULL);
CREATE TABLE hypothesis_assertion_identity (hypothesis_id INTEGER PRIMARY KEY REFERENCES hypothesis(hypothesis_id), assertion_id VARCHAR NOT NULL UNIQUE, relation_type VARCHAR NOT NULL, basis VARCHAR NOT NULL);
CREATE TABLE question_source (question_id INTEGER NOT NULL REFERENCES research_question(question_id), passage_id INTEGER NOT NULL REFERENCES source_passage(passage_id), source_role VARCHAR NOT NULL, attribution VARCHAR, record_status VARCHAR NOT NULL, scope_note VARCHAR, PRIMARY KEY(question_id, passage_id, source_role));
CREATE TABLE hypothesis_source (hypothesis_id INTEGER NOT NULL REFERENCES hypothesis(hypothesis_id), passage_id INTEGER NOT NULL REFERENCES source_passage(passage_id), source_role VARCHAR NOT NULL, attribution VARCHAR, record_status VARCHAR NOT NULL, scope_note VARCHAR, PRIMARY KEY(hypothesis_id, passage_id, source_role));
CREATE TABLE question_project_link (link_id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL REFERENCES research_question(question_id), project_ref_id INTEGER NOT NULL REFERENCES external_reference(external_ref_id), relation_type VARCHAR NOT NULL, passage_id INTEGER REFERENCES source_passage(passage_id), attribution VARCHAR, record_status VARCHAR NOT NULL, scope_note VARCHAR);
CREATE TABLE hypothesis_project_link (link_id INTEGER PRIMARY KEY, hypothesis_id INTEGER NOT NULL REFERENCES hypothesis(hypothesis_id), project_ref_id INTEGER NOT NULL REFERENCES external_reference(external_ref_id), relation_type VARCHAR NOT NULL, passage_id INTEGER REFERENCES source_passage(passage_id), attribution VARCHAR, record_status VARCHAR NOT NULL, scope_note VARCHAR);
CREATE VIEW workshop_question_model AS SELECT q.question_id, i.workshop_question_id, q.question_text, q.origin_kind, q.record_status, w.workshop_id, w.objective_id, w.source_cell FROM research_question q JOIN question_register_identity i ON i.question_id=q.question_id JOIN research_register.workshop_question w ON w.question_id=i.workshop_question_id;
CREATE VIEW workshop_rank_model AS SELECT q.question_id, q.workshop_question_id, r.reach_id, r.rank_value FROM workshop_question_model q JOIN research_register.workshop_rank r ON r.question_id=q.workshop_question_id;
CREATE VIEW proposed_hypothesis_science AS SELECT h.hypothesis_id, h.hypothesis_text, h.record_status, i.assertion_id, a.assertion_kind, a.extraction_status, a.limitation FROM hypothesis h JOIN hypothesis_assertion_identity i ON i.hypothesis_id=h.hypothesis_id JOIN research_register.science_assertion a ON a.assertion_id=i.assertion_id;
CREATE VIEW research_alignment_issues AS SELECT 'question worksheet endpoint or wording mismatch' AS issue, i.workshop_question_id AS local_id FROM question_register_identity i JOIN research_question q ON q.question_id=i.question_id LEFT JOIN research_register.workshop_question w ON w.question_id=i.workshop_question_id WHERE w.question_id IS NULL OR q.question_text<>w.question_text UNION ALL SELECT 'workshop question lacks canonical identity', w.question_id FROM research_register.workshop_question w LEFT JOIN question_register_identity i ON i.workshop_question_id=w.question_id WHERE i.question_id IS NULL UNION ALL SELECT 'hypothesis worksheet endpoint or wording mismatch', i.assertion_id FROM hypothesis_assertion_identity i JOIN hypothesis h ON h.hypothesis_id=i.hypothesis_id LEFT JOIN research_register.science_assertion a ON a.assertion_id=i.assertion_id WHERE a.assertion_id IS NULL OR h.hypothesis_text<>a.paraphrase;
